  const meta={"lt":{"title":"RentAll — daiktų nuoma netoliese","desc":"Nuomokitės daiktus iš žmonių ir verslų netoliese. Ieškokite pagal vietą, kategoriją, kiekį ir datas."},"en":{"title":"RentAll — Local Item Rentals","desc":"Rent items from people and businesses nearby. Search by location, category, quantity and dates."},"es":{"title":"RentAll — Alquiler de artículos cerca de ti","desc":"Alquila artículos de personas y empresas cercanas. Busca por ubicación, categoría, cantidad y fechas."},"de":{"title":"RentAll — Mietartikel in deiner Nähe","desc":"Miete Artikel von Menschen und Unternehmen in deiner Nähe. Suche nach Ort, Kategorie, Menge und Datum."},"ru":{"title":"RentAll — аренда вещей рядом","desc":"Арендуйте вещи у людей и компаний рядом. Ищите по месту, категории, количеству и датам."}};
  const originalText=new WeakMap();
  const originalAttrs=new WeakMap();
  const originalI18nHtml=new WeakMap();
  const skipTags=new Set(['SCRIPT','STYLE','NOSCRIPT','TEXTAREA']);
  let applying=false;

  function browserLocale(){
    const raw=(navigator.language||'').toLowerCase().split('-')[0];
    return SUPPORTED.includes(raw)?raw:'lt';
  }
  function current(){
    try{const saved=localStorage.getItem('rentall_language');if(SUPPORTED.includes(saved)) return saved;}catch{}
    return browserLocale();
  }
  function lookup(text,lang){
    const clean=String(text||'').trim();
    if(!clean) return null;
    if(lang==='en') return clean;
    return dictionaries[lang]?.[clean]||null;
  }
  function translateI18nElements(lang){
    document.querySelectorAll('[data-i18n]').forEach(el=>{
      const k=el.dataset.i18n;
      if(!originalI18nHtml.has(el)) originalI18nHtml.set(el,el.innerHTML);
      const translated=keyTranslations[lang]?.[k];
      if(translated!=null) el.innerHTML=translated;
      else if(lang==='en') el.innerHTML=keyTranslations.en?.[k]||originalI18nHtml.get(el);
    });
  }
  function withinKeyElement(node){
    const p=node.parentElement;
    return !!(p && p.closest('[data-i18n]'));
  }
  function translateTextNode(node,lang){
    if(!node||!node.parentElement||skipTags.has(node.parentElement.tagName)||withinKeyElement(node)) return;
    if(!originalText.has(node)) originalText.set(node,node.nodeValue);
    const original=originalText.get(node);
    const trimmed=String(original||'').trim();
    if(!trimmed) return;
    const translated=lookup(trimmed,lang);
    const lead=original.match(/^\s*/)?.[0]||'';
    const trail=original.match(/\s*$/)?.[0]||'';
    if(lang==='en') node.nodeValue=original;
    else if(translated) node.nodeValue=lead+translated+trail;
  }
  function translateAttrs(el,lang){
    const attrs=['placeholder','aria-label','title'];
    if(!originalAttrs.has(el)) originalAttrs.set(el,{});
    const bag=originalAttrs.get(el);
    for(const attr of attrs){
      if(el.hasAttribute(attr)&&bag[attr]===undefined) bag[attr]=el.getAttribute(attr);
      const original=bag[attr]; if(!original) continue;
      const translated=lookup(original,lang);
      if(lang==='en') el.setAttribute(attr,original); else if(translated) el.setAttribute(attr,translated);
    }
  }
  function translateTree(root,lang){
    if(!root) return;
    if(root.nodeType===3){translateTextNode(root,lang);return;}
    if(root.nodeType!==1&&root.nodeType!==9&&root.nodeType!==11) return;
    if(root.nodeType===1) translateAttrs(root,lang);
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);
    let n; while((n=walker.nextNode())){ if(n.nodeType===3) translateTextNode(n,lang); else translateAttrs(n,lang); }
  }
  function updateMeta(lang){
    document.documentElement.lang=lang;
    document.title=meta[lang]?.title||meta.en.title;
    const desc=document.querySelector('meta[name="description"]'); if(desc) desc.content=meta[lang]?.desc||meta.en.desc;
  }
  function apply(lang){
    if(!SUPPORTED.includes(lang)) lang='lt';
    applying=true;
    try{localStorage.setItem('rentall_language',lang)}catch{}
    updateMeta(lang);
    translateI18nElements(lang);
    translateTree(document.body,lang);
    const sel=document.getElementById('lang'); if(sel&&sel.value!==lang) sel.value=lang;
    applying=false;
    document.dispatchEvent(new CustomEvent('rentall:language-changed',{detail:{lang}}));
  }
  function t(key,vars){
    const lang=current(); let out=dictionaries[lang]?.[key]||keyTranslations[lang]?.[key]||(lang==='en'?key:null)||key;
    if(vars) for(const [k,v] of Object.entries(vars)) out=out.replaceAll(`{${k}}`,String(v));
    return out;
  }
  function populateSelector(){
    const sel=document.getElementById('lang'); if(!sel) return;
    sel.innerHTML='<option value="lt">LT</option><option value="en">EN</option><option value="es">ES</option><option value="de">DE</option><option value="ru">RU</option>';
    sel.value=current();
  }
  window.RentAllI18n={t,apply,getLanguage:current,supported:SUPPORTED,dictionaries,keyTranslations};
  function init(){
    populateSelector();
    const old=document.getElementById('lang');
    if(old){const clone=old.cloneNode(true);old.replaceWith(clone);clone.addEventListener('change',e=>apply(e.target.value));}
    apply(current());
    const observer=new MutationObserver(records=>{
      if(applying) return;
      const lang=current();
      requestAnimationFrame(()=>{
        applying=true;
        for(const r of records){
          if(r.type==='childList') r.addedNodes.forEach(n=>translateTree(n,lang));
          if(r.type==='characterData') translateTextNode(r.target,lang);
          if(r.type==='attributes') translateAttrs(r.target,lang);
        }
        translateI18nElements(lang);
        applying=false;
      });
    });
    observer.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title']});
  }
